cd /workspace && python3 -c "
import sys; sys.path.insert(0,'/workspace'); import wire; v=wire.v
import hashlib
tgt='899663737a71b5960d5d58a9946240921b51ab91efe10a8b6b25fdc845fe520e'
base=b'\xc0\x00\x00\x00\x01\x01\xaa\x01\xbb'
pn=1000000
cands=[]
for ln in range(0,10):
  for toklen in [b'\x00']:
    for pnbytes in [pn.to_bytes(3,'big'), pn.to_bytes(3,'little'), (pn%256).to_bytes(1,'big')+b'\x00\x00', b'\x00'+ (pn%(1<<16)).to_bytes(2,'big')]:
      b=base+toklen+v(ln)+pnbytes+b'\x01'
      cands.append(b)
for b in cands:
    if hashlib.sha256(b).hexdigest()==tgt: print('MATCH',b.hex())
print('tried',len(cands))
